/// Represents a TOML key/value type.
pub struct Map<K, V> {
    map: MapImpl<K, V>,
    dotted: bool,
    implicit: bool,
    inline: bool,
}

#[cfg(not(feature = "preserve_order"))]
type MapImpl<K, V> = BTreeMap<K, V>;
